pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(address actor, address newOwner) public {
        vm.assume(actor != address(this)); // any non-admin caller; admin is the deployer (this test contract)

        vm.prank(actor);
        bool ok;
        try c.setOwner(newOwner) { ok = true; } catch { ok = false; }

        // General rule: a non-admin caller can never change owner — the call reverts
        // and owner keeps its original value (the deployer).
        assertTrue(!ok && c.owner() == address(this));
    }
}

