pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(address caller, address newOwner) public {
        // Admin is the deployer (the test contract). Restrict caller to admin so the
        // call is admissible (onlyAdmin passes) and the return value is observable.
        address admin = address(this);
        vm.assume(caller == admin);
        vm.assume(newOwner != address(0));

        vm.prank(caller);
        bool ret = c.setOwner(newOwner);

        // Universal rule: whenever admin's setOwner completes, it reports success
        // (returns true). The mutant corrupts the returned success flag and can
        // report false, breaking the rule for fuzzed newOwner values.
        assertTrue(ret == true && c.owner() == newOwner);
    }
}

