pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(address first, address second) public {
        // admin is the deployer (this test contract); drive both calls from it
        vm.startPrank(address(this));
        (, bytes memory ret1) = address(c).call(abi.encodeWithSignature("setOwner(address)", first));
        (, bytes memory ret2) = address(c).call(abi.encodeWithSignature("setOwner(address)", second));
        vm.stopPrank();

        bool ok1 = ret1.length == 32 && abi.decode(ret1, (bool));
        bool ok2 = ret2.length == 32 && abi.decode(ret2, (bool));

        // General rule: every successful setOwner call by the admin reports success == true,
        // for ANY argument values (including a second call changing the owner).
        assertTrue(ok1 && ok2 && c.owner() == second);
    }
}

